import{_ as t,o,c as i,a0 as s}from"./chunks/framework.D-OzwTbp.js";const h=JSON.parse('{"title":"Description","description":"","frontmatter":{},"headers":[],"relativePath":"description.md","filePath":"description.md"}'),r={name:"description.md"};function a(n,e,d,c,p,l){return o(),i("div",null,[...e[0]||(e[0]=[s('<h1 id="description" tabindex="-1">Description <a class="header-anchor" href="#description" aria-label="Permalink to &quot;Description&quot;">​</a></h1><p><strong>gh-docs</strong> is a reusable setup for writing and publishing repository documentation. It combines:</p><ul><li><a href="https://vitepress.dev/" target="_blank" rel="noreferrer">VitePress</a> to turn Markdown files into static HTML.</li><li>GitHub Actions to build and publish the site to GitHub Pages.</li><li>Per-pull-request previews, with a link posted to each supported PR.</li><li>Automatic cleanup of a preview when its PR is merged or closed.</li></ul><p>The documentation app and its npm manifest are kept under <code>docs/</code>. Repositories written in Java, Go, or other languages do not need a root <code>package.json</code>.</p><h2 id="publishing-model" tabindex="-1">Publishing model <a class="header-anchor" href="#publishing-model" aria-label="Permalink to &quot;Publishing model&quot;">​</a></h2><p>The main branch site is published at the root of the Pages site. Each active same-repository PR gets a subdirectory such as <code>/pr-42/</code>. Closing a PR removes only its preview directory.</p><p>The pages are static output, so GitHub Pages does not run a Node.js server. Fork PR previews are skipped by default because their workflows do not have permission to publish or comment.</p><h2 id="repository-contents" tabindex="-1">Repository contents <a class="header-anchor" href="#repository-contents" aria-label="Permalink to &quot;Repository contents&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Path</th><th>Purpose</th></tr></thead><tbody><tr><td><code>docs/</code></td><td>Documentation source and VitePress project</td></tr><tr><td><code>docs/.vitepress/config.mts</code></td><td>Site title, sidebar, navigation, and base path</td></tr><tr><td><code>.github/workflows/deploy-docs.yml</code></td><td>This repository&#39;s deployment trigger and settings</td></tr><tr><td><code>.github/workflows/publish-docs.yml</code></td><td>Reusable build, publish, PR-comment, and cleanup workflow</td></tr></tbody></table><p>Continue to <a href="./consumers/">Consumers</a> for setup instructions.</p>',10)])])}const b=t(r,[["render",a]]);export{h as __pageData,b as default};
